#define smooth 10
#define MINSAMPLE int(pow(float(smooth)*3.14,2.)/4.)
#define applySmoothing 1
vec4 smoothP(vec2 pos) {
    int sampleN = 0;
    vec4 color = vec4(0);
    for (int y = -smooth;y<=smooth;y++) {
    for (int x = -smooth;x<=smooth;x++) {
    if (x*x + y*y <= smooth*smooth) {
        sampleN++;
        color += texture(iChannel0,(pos + vec2(x,y))/iResolution.xy);
    }
    }
    }
    if (sampleN < MINSAMPLE) {
        return vec4(0,0,0,1);
    }
    return color / float(sampleN);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    setSeed(uint(iResolution.x*fragCoord.y+fragCoord.x + float(hash(uint(iTime*1000.0))%1000u)));
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    #ifdef applySmoothing
    vec4 col = smoothP(fragCoord);
    #else
    vec4 col = texture(iChannel0,uv);
    #endif
    // Output to screen
    fragColor = col;
}

#define scatter 1
#define alwaysDown true
vec3 aliveColor() {
    float random = clamp(rand(),0.,1.);
    return vec3(1,1,0) * (1.-random) + vec3(1,0.5,0) * random;
}
int count(vec2 pos) {
    int sum = 0;
    for (int y = -1;y <= 1;y++) {
    for (int x = -1;x <= 1;x++) {
    if (length(fetchData(iChannel0,ivec2(pos + vec2(x,y))).xyz) > 0.0 && !(x == 0 && y ==0)) sum++;
    }
    }
    return sum;
}
vec3 updateCell(vec2 pos) {
    int neighbors = count(pos);
    bool alive = length(fetchData(iChannel0,ivec2(pos)).xyz) > 0.0;
    if ((neighbors < 2 || neighbors > 3) && alive) {
        return vec3(0);
    }
    if (neighbors == 3 && !alive) {
        return aliveColor();
    }
    return fetchData(iChannel0,ivec2(pos)).xyz;
}
vec4 handleMouse(vec2 pos,vec4 col) {
    vec2 rel = iMouse.xy - pos;
    if (iMouse.z > 0.0 || alwaysDown) {
        // pressed
        #ifdef scatter
        if (length(vec3(rand(),rand(),rand())) > 1.55) {
            return vec4(aliveColor(),1);
        } else {
            return col;
        }
        #else
        if (dot(rel,rel) < .64 && length(vec3(rand(),rand(),rand())) > 1.) {
            return vec4(aliveColor(),1);
        } else {
            return col;
        }
        #endif
    } else {
        return col;
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    setSeed(uint(iResolution.x*fragCoord.y+fragCoord.x + float(hash(uint(iTime*1000.0))%1000u)));
    fragColor = vec4(updateCell(fragCoord),1.0);
    // check mouse
    fragColor = handleMouse(fragCoord,fragColor);
}

// random generation was borrowed from https://www.shadertoy.com/view/dtyGWR
#define fetchData(buf, addr) texelFetch(buf, addr, 0)

#define storeData(buf_pos, addr) ivec2(buf_pos) == addr

const ivec2 FS_ADDR = ivec2(0.0);

const vec4 fs_stt = vec4(1.0);

uint seed = 0u;

void setSeed(uint s) {
    seed = s;
}

uint hash(uint s) {
    s ^= 2747636419u;
    s *= 2654435769u;
    s ^= s >> 16;
    s *= 2654435769u;
    s ^= s >> 16;
    s *= 2654435769u;
    return s;
}

uint randI() {
    seed = hash(seed);
    return seed;
}

float rand() {
    uint rn = randI();
    rn %= 1000000000u;
    float rs = float(rn);
    rs /= 1000000000.0;
    return rs;
}

